import java.util.Scanner;

public class cf1342e {

    static int[] fact;
    static int[] ifact;
    static int fmod = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long kl = sc.nextLong();
        if (kl >= n) {
            System.out.println(0);
            sc.close();
            return;
        }
        int k = (int) kl;
        fact = new int[n + 1];
        ifact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int)((long)fact[i - 1] * i % fmod);
        }
        int ans = 0;
        int mult = 1;
        for (int i = 0; i <= n - k; i++, mult = -mult) {
            int add = mult * fmul(fpow(n - k - i, n), fmul(fact[n - k], fmul(ifact[i], ifact[n - k - i])));
            while (add < 0) add += fmod;
            ans += add;
            if (ans >= fmod) ans -= fmod;
        }
        int res = (int)((long)fmul(fmul(ans, fact[n]), fmul(ifact[k], ifact[n - k])) % fmod);
        if (k == 0) {
            System.out.println(res);
        } else {
            System.out.println(fmul(res, 2));
        }
        sc.close();
    }

    static int ifact(int x) {
        if (ifact[x] > 0) {
            return ifact[x];
        } else {
            return ifact[x] = fpow(fact[x], fmod - 2);
        }
    }

    static int fpow(int a, int b) {
        int result = 1;
        int base = a;
        int exp = b;
        while (exp > 0) {
            if ((exp & 1) == 1) result = fmul(result, base);
            base = fmul(base, base);
            exp >>= 1;
        }
        return result;
    }

    static int fmul(int a, int b) {
        return (int)((long)a * b % fmod);
    }
}
